function parseJSON(txt){ txt=String(txt||'').trim(); if(txt.charAt(0)!=='{') return null; try{ return JSON.parse(txt); }catch(e){ return null; } }
var bu=String(baseUrl);
var mm=bu.match(/novels\/(\w+)\/chapters\/(\d+)/) || bu.match(/[?&]novel=(\w+).*?[?&]chapter=(\d+)/);
var d=parseJSON(result);
if(!d||!d.chapter){
  if(!mm) throw 'Không đọc được chương: thiếu id truyện hoặc số chương';
  var api='https://novelarchive.st/api/novels/'+mm[1]+'/chapters/'+mm[2];
