    var u=java.get(String(api), {'User-Agent':UA,'Accept':'application/json, text/plain, */*','Accept-Language':'vi-VN,vi;q=0.9','Referer':'https://novelarchive.st/reader?novel='+mm[1]+'&chapter='+mm[2],'Authorization':'Bearer '+tk});
    d=parseJSON(u.body());
    if(!d||!d.chapter){ java.put('na_token',''); d=null; }
  }
  if(!d||!d.chapter){ d=parseJSON(GH(api)); }
}
if(!d||!d.chapter){
  var em=(d&&(d.error||d.msg||d.detail))||'';
  if(!d) throw 'Trang trả về nội dung lạ (có thể Cloudflare chặn) — thử lại sau ít phút.';
