if(!t) throw 'Chương này trống (có thể cần đăng nhập hoặc đang khoá)';
t=t.replace(/^\s*Settings\s*\n[\s\S]{0,240}?Background Color\s*(\n\s*)*/,'');
t=t.replace(/\s*[\u2726\u2736\u2727\u2733\*\u00b7\s]{0,12}Want to read ahead\?[\s\S]*$/,'');
var nm=String((d.chapter&&d.chapter.name)||'').replace(/^\s*chapter\s*\d+\s*[:.\-]\s*/i,'').trim();
if(nm){ var esc=nm.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'); t=t.replace(new RegExp('^\\s*'+esc+'\\s+'+esc+'\\s*'),''); }
t=t.replace(/^\s*(.{6,90}?)\s+\1(?=\s|$)/,'$1');
t=t.replace(/src=["']\/\/[^"'\s>]+/g,'src="https://novelarchive.st/');
t=t.replace(/src=["']\/(?!\/)/g,'src="https://novelarchive.st/');
